   "hitokoto": "ブランド名やロゴを、光の粒が形づくって見せるオープニングに。世界のお手本の棚にある Fluoddity（光の粒が自分で集まって、細胞や星の形になる作品）に寄せて作った、おけもん版の15秒。黒地に約20万の光の粒だけで、ひと呼吸ごとに姿を変える：細胞 → 穴のあいた蜂の巣 → 放射と渦 → 色とりどりの星 → おけもんの活動の名前「おけ森」の字。最後は字の輪郭だけが残り、まわりを色とりどりの仲間が漂う。粒の位置は時刻からの式で決まるので、どのコマから書き出しても同じ絵になる。曲はおけもんの自作の瞑想の曲（感謝編）。",
