    "text": "あなたが今できる最高のモーショングラフィックで、見た人が思わず「すごい」と声に出す1本を作ってください。\nいま世界中で話題の「AIが本気で作るモーショングラフィック」です。あなたの腕前を、出し惜しみせず全力で証明してください。\n\n■ 作りたいもの（本人の言葉）\n架空のボルダリングジムの6周年を数字で：黒×黄で「登った回数」「最年少の会員」などの数字がスロットのように回って止まり、黄色い四角が広がって次の数字へ\n\n■ お手本（この1本のテンポ・文字・切り替えに寄せる）\n- お手本：BNB Chain の6周年（黒と黄色、値段の数字がスロットのように回る）（BNB Chain） https://x.com/BNBCHAIN/status/2094757311080444274\n- 特徴：黒と黄色の2色、背景に画面からはみ出す巨大な文字／値段の数字がスロットのように縦に回って入れ替わる／アイコンが1個ずつ並び、増減の％が横に流れ続ける／黄色い四角が広がって場面が替わる・語りの声つき\n- 動画が見られなくても大丈夫。上の特徴に寄せて作る。お手本の色・ロゴ・言葉・キャラはそのまま使わず、「作りたいもの」に置きかえる\n- 作業フォルダにお手本のスクリーンショットがあれば、それも見て寄せる\n\n■ 仕上がりのイメージ\nワクワクするように、元気いっぱいのお祝い。15秒。丸や三角がリズムよく並び替わり、数字やグラフが気持ちよく伸びる。少しずつ時間差で順番に動き、色の面がシャッと画面を入れ替える。最後に「最年少の会員」が大きく残る。\n\n■ 使ってほしい演出（これは出発点です。もっと良い見せ方を思いついたら、そちらを選んでかまいません）\n1. シェイプアニメーション（Shape Animation）：丸・三角・四角などの図形がリズムよく並び、回り、組み替わる\n2. インフォグラフィック・アニメーション（Animated Infographics）：数字のカウントアップ、グラフが伸びる動きで、情報を気持ちよく見せる\n3. キネティック・タイポグラフィ（Kinetic Typography）：画面に出す言葉を主役にして、文字ごとに登場と退場の動きをつける\n4. カラーワイプ（Color Wipe）：大きな色の面が画面を横切り、背景の色ごと場面を切り替える\n5. スタッガー（Stagger）：複数の要素をほんの少しずつ時間差で動かし、波のような流れを作る\n6. オーバーシュート（Overshoot）：目標の位置を少し行き過ぎてから戻る、バネの動き\n7. ライトスイープ（Light Sweep）：光の筋が表面を横切ってきらっと輝く。光のにじみ（グロー）も少し\n8. ビートシンク（Beat Sync）：テンポを1つ決め、場面の切り替えや大事な動きを拍に合わせる。効果音も動きと同じ瞬間に鳴らす\n\n■ 条件\n- 長さ：15秒　画面：横長 16:9（1920×1080）\n- 形式：HTMLファイル1枚（HTML・CSS・JavaScriptをすべてこの中にまとめる）。今いる作業フォルダに motion.html として保存し（同じ名前があれば motion-2.html のように番号をつける）、できたらブラウザで開く（Mac なら open コマンド）\n- 再生：最後まで行ったら「もう一度見る」ボタンを出す\n- 外部のライブラリを使う時は CDN から読み込む（three.js など）。フォントはパソコンに入っている日本語フォントを使う\n- 時間の管理：すべての動きを1本のタイムライン（経過時間から各場面の状態を計算する形）で管理し、コマ落ちしても時間どおりに進むようにする\n- 音：Web Audio API で、BGM（テンポ 125BPM 前後）と効果音をコードだけで作る。ブラウザの決まりで最初は音が出ないので、最初の画面に大きな「▶ 音つきで再生」ボタンを置き、押したら映像と音を同時に始める。大事な動きと効果音は同じ瞬間に\n- 画面に出す言葉：「登った回数」「最年少の会員」（どれも一字一句そのまま使う）\n- 色：明るい白に、朱赤と紺、ひとさじの黄色（元気さを少し）（例：#FFF8F0 #FF5A36 #1E2A78 #FFC93C）\n- 文字：日本語は読みやすい太さのフォントで。小さすぎる文字は使わない\n\n■ いちばん大事なこと\n- いちばん大事なのは「作りたいもの（本人の言葉）」。上の『仕上がりのイメージ』『使ってほしい演出』『色』が本人の言葉と食い違うところは、本人の言葉を優先する\n- 演出を並べるだけにしない。ひとつの芯のアイデア（たとえば最初に出た形が最後まで姿を変え続ける）で、全部の場面をつなぐ\n- その芯は、説明がなくても画面を見るだけで伝わるようにする\n- 場面の切れ目はパッと切らず、前の場面の形を次の場面へ受け渡してつなぐ\n- 動きは等速にしない。加速・減速（イージング）と、止める瞬間（間）をつける\n- キャラクターや動物の絵をコードで描かない。図形・文字・模様・光・3Dの形で表現する（写真やイラストのファイルを渡された時だけ、それを使う）\n\n作り始める前に、芯のアイデアと場面の流れを3行で書き出してから作ってください。\n完成したら、使った演出と、芯のアイデアを1行ずつ教えてください。",
