    "text": "あなたが今できる最高のモーショングラフィックで、見た人が思わず「すごい」と声に出す1本を作ってください。\nいま世界中で話題の「AIが本気で作るモーショングラフィック」です。あなたの腕前を、出し惜しみせず全力で証明してください。\n\n■ 作りたいもの（本人の言葉）\n解説「AIに頼む前の1行」（横長 16:9・20秒）：入力欄に「いい感じの動画つくって」と打たれ、「だれに」「なにを」「どんな感じで」の3つの問いが付箋のように順に現れて、1行が書き換わり、カメラが送信ボタンへ寄る。初心者が自分の1行に置きかえられる言葉だけで、専門用語は出さない。入力欄も付箋も HTML の図形、音は打鍵と送信を Web Audio で合成\n\n■ お手本（この1本のテンポ・文字・切り替えに寄せる）\n- お手本：Claude Code と Remotion で、デモ動画のモーションを全部作った（Tim Kochjar） https://x.com/timkochjar/status/2092278549679886507\n- 特徴：小さな字が1語ずつ出て、決めの語だけ大きく青い下地／傾けたアプリ画面にカメラが寄り、カーソルで操作／カットせず、ぼかし＋ズームでつなぐ／低音の電子音楽に、ヒュッ・ポッの効果音\n- 動画が見られなくても大丈夫。上の特徴に寄せて作る。お手本の色・ロゴ・言葉・キャラはそのまま使わず、「作りたいもの」に置きかえる\n- 作業フォルダにお手本のスクリーンショットがあれば、それも見て寄せる\n\n■ 仕上がりのイメージ\nやさしく、近未来の解説。20秒。アプリの画面が動いて使い方を見せ、丸や三角がリズムよく並び替わる。少しずつ時間差で順番に動き、カメラが静かに寄っていく。最後に要点がひと目でわかる形で止まる。\n\n■ 使ってほしい演出（これは出発点です。もっと良い見せ方を思いついたら、そちらを選んでかまいません）\n1. UIアニメーション（UI Animation）：架空のスマホやPCの画面を作り、ボタンやカードが動いて操作の流れを見せる\n2. シェイプアニメーション（Shape Animation）：丸・三角・四角などの図形がリズムよく並び、回り、組み替わる\n3. カットアウト・アニメーション（Cutout Animation）：紙を切り抜いたような形が重なり、影つきで貼られたり剥がれたりする\n4. プッシュイン（Push-in）：カメラがゆっくり寄っていく（途中で止めず、なめらかに）\n5. マスクリビール（Mask Reveal）：マスク（見えない窓）で文字や形を少しずつ見せる\n6. スタッガー（Stagger）：複数の要素をほんの少しずつ時間差で動かし、波のような流れを作る\n7. ブリージング（Breathing Animation）：光や形が、呼吸のようにゆっくりふくらんでしぼむ（ループ作品なら、切れ目なくつなぐ）\n8. ライトスイープ（Light Sweep）：光の筋が表面を横切ってきらっと輝く。光のにじみ（グロー）も少し\n9. アンビエントサウンド（Ambient Sound Design）：BGMは静かなパッドやオルゴールのような音にして、効果音は大事な瞬間だけ小さく鳴らす\n\n■ 条件\n- 長さ：20秒　画面：横長 16:9（1920×1080）\n- 形式：HTMLファイル1枚（HTML・CSS・JavaScriptをすべてこの中にまとめる）。今いる作業フォルダに motion.html として保存し（同じ名前があれば motion-2.html のように番号をつける）、できたらブラウザで開く（Mac なら open コマンド）\n- 再生：最後まで行ったら「もう一度見る」ボタンを出す\n- 外部のライブラリを使う時は CDN から読み込む（three.js など）。フォントはパソコンに入っている日本語フォントを使う\n- 時間の管理：すべての動きを1本のタイムライン（経過時間から各場面の状態を計算する形）で管理し、コマ落ちしても時間どおりに進むようにする\n- 音：Web Audio API で、BGM（テンポ 90BPM 前後の静かな曲）と効果音をコードだけで作る。ブラウザの決まりで最初は音が出ないので、最初の画面に大きな「▶ 音つきで再生」ボタンを置き、押したら映像と音を同時に始める。大事な動きと効果音は同じ瞬間に（効果音は控えめに）\n- 画面に出す言葉：「いい感じの動画つくって」「だれに」「なにを」「どんな感じで」「秋の古着屋の告知を、縦長15秒で、やさしい感じで」「AIに頼む前の1行」（どれも一字一句そのまま使う）\n- 色：生成り、セージグリーン、淡い水色（近未来っぽさを少し）（例：#F3F5EF #A8C5B5 #6E9FB5 #F2E3C4 #3E4A46）\n- 文字：日本語は読みやすい太さのフォントで。小さすぎる文字は使わない\n\n■ いちばん大事なこと\n- いちばん大事なのは「作りたいもの（本人の言葉）」。上の『仕上がりのイメージ』『使ってほしい演出』『色』が本人の言葉と食い違うところは、本人の言葉を優先する\n- 「すごい」は派手さのことではない。静かな作品なら、静けさと美しさで「すごい」と言わせる\n- 演出を並べるだけにしない。ひとつの芯のアイデア（たとえば最初に出た形が最後まで姿を変え続ける）で、全部の場面をつなぐ\n- その芯は、説明がなくても画面を見るだけで伝わるようにする\n- 場面の切れ目はパッと切らず、前の場面の形を次の場面へ受け渡してつなぐ\n- 動きは等速にしない。加速・減速（イージング）と、止める瞬間（間）をつける\n- キャラクターや動物の絵をコードで描かない。図形・文字・模様・光・3Dの形で表現する（写真やイラストのファイルを渡された時だけ、それを使う）\n\n作り始める前に、芯のアイデアと場面の流れを3行で書き出してから作ってください。\n完成したら、使った演出と、芯のアイデアを1行ずつ教えてください。",
